// === Tab: mySketch ===
// Attractor_25.0

let N = 10000 ; let WB = 80 ; let GB = 10000 ;
let H = 7 ; let dA = 0.01 ; let G = 0.01 ; let S = 0.99 ; 

let W[] = new Array(N) ; let dW[] = new Array(N) ;
let I ; let A ; let AA ; let GX ; let GY ;
let X ; let Y ; let Z ; let XX ; let YY ; let ZZ ;

function setup(){
  createCanvas(900, 400) ; background(0) ; noSmooth() ; 
  for ( I = 0 ; I < N ; I++ ){
     W[I] =  W[0]+random(-0.01,+0.01) ;
    dW[I] = dW[0]+random(-0.01,+0.01) ;
  }//I
}//setup()

function draw(){
  background(0) ; strokeWeight(1) ; 
  AA = A*H ;
  X = 0 ; Y = 0 ; Z = G ;
  XX = (X*cos(A))-(Z*sin(A)) ;
  ZZ = (X*sin(A))+(Z*cos(A)) ;
  X = XX ; Z = ZZ ;
  XX = (X*cos(AA))-(Y*sin(AA)) ;
  YY = (X*sin(AA))+(Y*cos(AA)) ;
  X = XX ; Y = YY ;
  for ( I = 0 ; I < N ; I++ ){
    dW[I] = (dW[I]-(X*sin(W[I]))+(Z*cos(W[I])))*S ;
    W[I] = W[I]+dW[I] ;
    while( W[I] > +PI ){ W[I] = W[I]-(2*PI) ; } 
    while( W[I] < -PI ){ W[I] = W[I]+(2*PI) ; } 
    point(+W[I]*WB+600,-dW[I]*WB*10+200) ;
  }//let A = A+dA ;
  GX = 60*cos(W[0]) ; GY = 60*sin(W[0]) ; strokeWeight(2) ; 
  noStroke() ; fill(120) ; arc(150,200,200,200,W[0]-(PI/2),W[0]+(PI/2)) ; ellipse(150,200,60,60) ;
  fill(0) ; ellipse(150,200,20,20) ;
  stroke(255) ; fill(255) ; line(150+GX,200+GY,X*GB+150+GX,Z*GB+200+GY) ;
  XX = ((X*cos(+PI*0.8))-(Z*sin(+PI*0.8)))*0.2 ; ZZ = ((X*sin(+PI*0.8))+(Z*cos(+PI*0.8)))*0.2 ; 
  line(X*GB+150+GX,Z*GB+200+GY,(X+XX)*GB+150+GX,(Z+ZZ)*GB+200+GY) ;
  XX = ((X*cos(-PI*0.8))-(Z*sin(-PI*0.8)))*0.2 ; ZZ = ((X*sin(-PI*0.8))+(Z*cos(-PI*0.8)))*0.2 ; 
  line(X*GB+150+GX,Z*GB+200+GY,(X+XX)*GB+150+GX,(Z+ZZ)*GB+200+GY) ;
  ellipse(150+GX,200+GY,8,8) ; noFill() ;
  line(350,200,850,200) ; line(850,200,840,190) ; line(850,200,840,210) ; 
  line(600,50,600,350) ; line(600,50,590,60) ; line(600,50,610,60) ;
  ellipse(860,200,10,20) ; line(855,200,865,200) ; ellipse(605,40,10,20) ; line(600,40,610,40) ;
  ellipse(590,45,10,10) ; line(595,30,595,50) ;
}//draw()

